# =========================================================================
# 6. INGESTION & DATASET COMPILATION PIPELINE
# =========================================================================
def run_ingestion():
    print("Ingesting Week 04 data across webapp and root databases...")

    # A. Build Varsity Bank
    # Varsity has Pure Varsity (48) + Shared Repeats (24) = 72 items (exact multiple of 12)
    varsity_w4 = list(PURE_VARSITY)
    for q in SHARED_REPEATS:
        q_copy = dict(q)
        q_copy["track"] = "varsity"
        varsity_w4.append(q_copy)

    # B. Build Medical Bank
    # Medical has Pure Medical (24) + Shared Repeats (24) = 48 items (exact multiple of 12)
    medical_w4 = list(PURE_MEDICAL)
    for q in SHARED_REPEATS:
        q_copy = dict(q)
        q_copy["track"] = "medical"
        medical_w4.append(q_copy)

    # C. Build Union Quizzes / Questions
    # 48 pure var + 24 shared + 24 pure med = 96 items (exact multiple of 12)
    all_w4_map = {}
    for q in PURE_VARSITY:
        all_w4_map[q["id"]] = q
    for q in SHARED_REPEATS:
        all_w4_map[q["id"]] = q
    for q in PURE_MEDICAL:
        all_w4_map[q["id"]] = q
    all_w4 = list(all_w4_map.values())

    print(f"Week 04 Counts: Varsity={len(varsity_w4)}, Medical={len(medical_w4)}, Union={len(all_w4)}")

    # Update Varsity Bank
    for vpath in [
        os.path.join(DATA_DIR, "varsity_bank.json"),
        os.path.join(BASE_DIR, "varsity_bank.json")
    ]:
        if os.path.exists(vpath):
            with open(vpath, "r", encoding="utf-8") as f:
                data = json.load(f)
            data = [item for item in data if item.get("week_id") != "week_04"]
            data.extend(varsity_w4)
            with open(vpath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            print(f"Updated {vpath} (Total items: {len(data)})")

    # Update Medical Bank
    for mpath in [
        os.path.join(DATA_DIR, "medical_bank.json"),
        os.path.join(BASE_DIR, "medical_bank.json")
    ]:
        if os.path.exists(mpath):
            with open(mpath, "r", encoding="utf-8") as f:
                data = json.load(f)
            data = [item for item in data if item.get("week_id") != "week_04"]
            data.extend(medical_w4)
            with open(mpath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            print(f"Updated {mpath} (Total items: {len(data)})")

    # Update Quizzes and Questions
    for qpath in [
        os.path.join(DATA_DIR, "quizzes.json"),
        os.path.join(DATA_DIR, "questions.json"),
        os.path.join(BASE_DIR, "questions.json")
    ]:
        if os.path.exists(qpath):
            with open(qpath, "r", encoding="utf-8") as f:
                data = json.load(f)
            data = [item for item in data if item.get("week_id") != "week_04"]
            data.extend(all_w4)
            with open(qpath, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            print(f"Updated {qpath} (Total items: {len(data)})")

    # Update weeks.json
    weeks_path = os.path.join(DATA_DIR, "weeks.json")
    if os.path.exists(weeks_path):
        with open(weeks_path, "r", encoding="utf-8") as f:
            weeks_data = json.load(f)
        weeks_data = [w for w in weeks_data if w.get("id") != "week_04"]
        # Insert Week 04 in order
        week_04_entry = {
            "id": "week_04",
            "name": "Week 04",
            "badge": "পদার্থের গাঠনিক ধর্ম ও আদর্শ গ্যাস, পর্যায়বৃত্ত ধর্ম ও বন্ধন, বিন্যাস-সমাবেশ ও সম্ভাবনা, প্রাণীর শ্রেণিবিন্যাস ও জিনতত্ত্ব",
            "description": "৮০/২০ হাই-ইল্ড মাল্টি-স্ট্রিম কোর: পৃষ্ঠটান ও আরএমএস বেগ, ফাজানের নীতি ও সংকরায়ন, প্যাসকেলের সমাবেশ সূত্র ও বিস্তার পরিমাপ, সিলোম ও মেন্ডেলীয় ব্যতিক্রম।",
            "subjects": [
                "Physics",
                "Chemistry",
                "Higher Math",
                "Biology",
                "English",
                "GK"
            ],
            "total_mcqs": len(all_w4),
            "total_slides": 16,
            "total_flashcards": 65
        }
        # Insert before week_06 if exists
        idx = len(weeks_data)
        for i, w in enumerate(weeks_data):
            if w.get("id") == "week_06":
                idx = i
                break
        weeks_data.insert(idx, week_04_entry)
        with open(weeks_path, "w", encoding="utf-8") as f:
            json.dump(weeks_data, f, ensure_ascii=False, indent=2)
        print(f"Updated {weeks_path} with Week 04 metadata.")

    # Update predictor_sets.json with Week 04 prediction sets & written problems
    pred_path = os.path.join(DATA_DIR, "predictor_sets.json")
    pred_root_path = os.path.join(BASE_DIR, "predictor_sets.json")
    for pfile in [pred_path, pred_root_path]:
        if os.path.exists(pfile):
            with open(pfile, "r", encoding="utf-8") as f:
                psets = json.load(f)
            
            vsets = psets.get("varsity_sets", [])
            vsets = [s for s in vsets if s.get("id") != "var_pred_set_04"]
            vsets.append({
                "id": "var_pred_set_04",
                "title": "🎯 DU 'Ka' Week 04 80/20 Multi-Stream Master Prediction Set",
                "track": "varsity",
                "duration_minutes": 60,
                "total_marks": 100,
                "negative_marking": 0.25,
                "badge": "Week 04 Master 80/20",
                "description": "পদার্থের গাঠনিক ধর্ম ও আদর্শ গ্যাস, পর্যায়বৃত্ত ধর্ম ও বন্ধন, বিন্যাস-সমাবেশ ও বিস্তার পরিমাপ এবং প্রাণীর শ্রেণিবিন্যাস ও জিনতত্ত্ব সমন্বিত পূর্ণাঙ্গ মডেল সেট।",
                "syllabus_scope": "Week 04 Full 80/20 Core Syllabus",
                "subjects": ["Physics", "Chemistry", "Higher Math", "Biology"],
                "target_mcqs": 60,
                "written_included": True,
                "written_problems": DU_WRITTEN_SPECIALS
            })
            psets["varsity_sets"] = vsets

            msets = psets.get("medical_sets", [])
            msets = [s for s in msets if s.get("id") != "med_pred_set_04"]
            msets.append({
                "id": "med_pred_set_04",
                "title": "🩺 Medical Week 04 80/20 Multi-Stream Master Prediction Set",
                "track": "medical",
                "duration_minutes": 60,
                "total_marks": 100,
                "negative_marking": 0.25,
                "badge": "Week 04 MAT Master 80/20",
                "description": "গাজী আজমল ও আবুল হাসান স্যারের পাঠ্যবইয়ের প্রত্যক্ষ লাইন, প্রাণীর শ্রেণিবিন্যাস, অপদ্রব্যের পৃষ্ঠটান প্রভাব, ইংরেজি ইনভার্শন ও সংবিধান-মুক্তিযুদ্ধ জিকে সমন্বিত মডেল টেস্ট।",
                "syllabus_scope": "Week 04 Medical Core Syllabus",
                "subjects": ["Biology", "Chemistry", "Physics", "English", "GK"],
                "target_mcqs": 60,
                "written_included": False
            })
            psets["medical_sets"] = msets

            with open(pfile, "w", encoding="utf-8") as f:
                json.dump(psets, f, ensure_ascii=False, indent=2)
            print(f"Updated {pfile} with Week 04 prediction sets.")

    # Update vault.json
    vault_path = os.path.join(DATA_DIR, "vault.json")
    if os.path.exists(vault_path):
        with open(vault_path, "r", encoding="utf-8") as f:
            vault_data = json.load(f)
        
        entries = vault_data.get("entries", [])
        existing_v_ids = set(e["id"] for e in entries)
        for ventry in WEEK_04_VAULT_ENTRIES:
            if ventry["id"] in existing_v_ids:
                entries = [e for e in entries if e["id"] != ventry["id"]]
            entries.append(ventry)
        vault_data["entries"] = entries
        
        with open(vault_path, "w", encoding="utf-8") as f:
            json.dump(vault_data, f, ensure_ascii=False, indent=2)
        print(f"Updated {vault_path} with Week 04 vault entries (Total: {len(entries)}).")

if __name__ == "__main__":
    run_ingestion()
